export const SVGText = ({
  text,
  className = '',
  style = {},
  fill = '',
  width,
  height,
  ...props
}) => {
  const cfg = textMap[text];

  if (!cfg) return null;

  const {
    viewBox,
    dataAsc,
    d,
    width: defaultWidth,
    height: defaultHeight
  } = cfg;

  return (




    <svg
      className={className}
      style={style}
      fill={fill}
      width={width ?? defaultWidth}
      height={height ?? defaultHeight}
      viewBox={viewBox}
      data-asc={dataAsc}
      {...props}
    >
      <defs />
      <g fill={fill}>
        <g transform="translate(0, 0)">
          <path d={d} fill={fill} />
        </g>
      </g>
    </svg>


  );
};



