export const DrawText = ({
  children,
  duration = DEFAULT_DURATION,
  stagger = 0.5,
  strokeWidth = 2,
  className = "",
  style = {},
  stroke = "currentColor" // take also 'border' and 'low' 
}) => {
  const containerRef = useRef(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const paths = containerRef.current.querySelectorAll("path");

    // Reveal container after processing is ready to start (prevents flash of unstyled content)
    containerRef.current.style.opacity = 1;

    paths.forEach((path, i) => {
      const length = path.getTotalLength();

      // Force stroke mode
      path.style.fill = "none";
      path.style.stroke =
        stroke === "border" ? "var(--border-color, currentColor)" :
          stroke === "low" ? "var(--low-color, currentColor)" : "currentColor";
      path.style.strokeWidth = strokeWidth;
      path.style.strokeDasharray = length;
      path.style.strokeDashoffset = length;
      path.style.opacity = 1;

      // Trigger layout
      path.getBoundingClientRect();

      path.style.transition = `
        stroke-dashoffset ${duration}s ease
      `;

      path.style.transitionDelay =
        `${i * stagger + Math.random() * 0.08}s`;

      path.style.strokeDashoffset = 0;
    });
  }, [duration, stagger, strokeWidth]);

  return (
    <div
      ref={containerRef}
      className={className}
      style={{ color: "#000", opacity: 0, height: "fit-content", ...style }}
    >
      {children}
    </div>
  );
};


